#include <stdio.h>



int main(void) {
    int n, prime = 1;
    scanf("%d", &n);
    for (int d = 2; d <= n / d; d++) if (n % d == 0) { prime = 0; break; }
    puts(prime ? "YES" : "NO");
    return 0;
}
